%% Show_Compared_Results_Lib24_ALL_reduced_model_set_dma
% Compare parameter estimates and objective values across fixed d_mA values.
%
% Loads the compiled Lib24 tensors for d_mA = 0.15, 0.17, 0.20, 0.22, and
% 0.25 min^-1 and compares the optimization outcomes for plasmid, promoter,
% and RBS parameters.
%
% Required files are generated by
% Generate_Results_Lib24_ALL_reduced_model_set_dma.m.
%
% USAGE
%   Show_Compared_Results_Lib24_ALL_reduced_model_set_dma
%
% See README.md for the complete workflow.

% --- Portable project initialization (no absolute paths) ---
ROOT = init_SynTwin();  % Scripts_base + HEM_Surrogate are added by default
% Absolute path to the folder where this script lives (model folder)
SCRIPT_DIR = fileparts(mfilename('fullpath'));
addpath(SCRIPT_DIR);

% Consider an exogenous circuit. We use a Transcriptional Unit (TU) expressing GFP:
model_c.lp_c = 240; %Length of GFP protein (aa)     
model_c.le_c = model_c.lp_c^0.097/0.0703; 	%Ribosome occupancy length (aa) %lea=la^0.097/0.0703
model_c.Em_c =  model_c.lp_c/model_c.le_c*(1- (model_c.lp_c/(model_c.lp_c+model_c.le_c))^(model_c.lp_c/model_c.le_c)) ;  
model_c.WEm_c =  1 + 1/model_c.Em_c;  
model_c.N_pSC101 = 5; %known

 indices_plasmids = [1,2];
 indices_promoters = [1,2,3];
 indices_rbss = [1,2,4,5];


 Lower_Bounds = [0.025,0.05,0.05... %lower expected bounds for omega, promoter strengths,
          0.05, 2.5e-3, 0.05, 2.5e-3,2.5e-3 ...  %lower expected bounds for RBS_k0_sigma0, 
          2.5 ];  %lower expected bound for high copy number multiplying term 

    Upper_Bounds = [0.15,0.35,0.35... %upper expected bounds for omega, promoter strengths,
          2.0, 10e-3, 0.35, 8e-3,2e-2 ...  %upper expected bounds for RBS_k0_sigma0, 
          8.25 ];  %upper expected bound for high copy number multiplying term 

% Getting the Results structure corresponding to the estimated parameters
% of Lib24 with the reduced model 
% CHANGE BETWEEN Global, Instances and Wells appropriately

%Use_mean = 'Instances';  
%Use_mean = 'Global';  
Use_mean = 'Wells'; 

set_dma = [0.15,0.17,0.20,0.22,0.25];
RBS_inv_sigma0 = 0.02;

labels = arrayfun(@(x) sprintf('$d_{mA}=%.3g$', x), set_dma, 'UniformOutput', false);

RBS_colors= hex2rgb(['#A8DADC';'#F4A261';'#B5E48C';'#CDB4DB';'#FFE066']);

 for i= 1:numel(set_dma)
 
    model_c.dm_c  = set_dma(i); %Mean degradation rate of non-ribosomal mRNA (1/min) 
    
    file_name = "Results_Tensor_Lib24_ALL_reduced_model_"  + Use_mean + "_dma_" + extractAfter(num2str(model_c.dm_c), '.') + ".mat";

    load(fullfile(SCRIPT_DIR,file_name));

   Results_Tensor_case{i}.Results_Tensor_Lib24_ALL_reduced = Results_Tensor_Lib24_ALL_reduced;
   Results_parameters_case{i}.Estimated_parameters = Estimated_parameters;
 end


% 
% title_text = 'Lib24. ALL. RM.';
% 
% Plot_Results_Lib_reduced_model(Results_Tensor_Lib24_ALL_reduced,Lower_Bounds,Upper_Bounds,indices_plasmids,indices_promoters,indices_rbss, title_text)

 
   h = gobjects(numel(set_dma),1);

    figure('Name','Estimate vs cost Ori','Color','w');
    tiledlayout(1,1,'Padding','compact','TileSpacing','compact');
    nexttile
    for j = 1:numel(set_dma)
         h(j) = scatter(5*Results_parameters_case{j}.Estimated_parameters.ALL_raw(:,8),Results_parameters_case{j}.Estimated_parameters.J_raw,35,RBS_colors(j,:),'filled');
         hold on
    end
    legend(h, labels, 'Interpreter','latex','Location','best');
    xlabel('$\hat{\theta}$','Interpreter','latex');
    ylabel('$J$','Interpreter','latex');
    grid on;


figure('Name','Estimate vs Cost Promoter','Color','w');
tiledlayout(1,3,'Padding','compact','TileSpacing','compact');
for i = 1:3
    nexttile
    for j = 1:numel(set_dma)
         h(j) =  scatter(Results_parameters_case{j}.Estimated_parameters.ALL_raw(:,i),Results_parameters_case{j}.Estimated_parameters.J_raw,35,RBS_colors(j,:),'filled');
         hold on
    end
    legend(h, labels, 'Interpreter','latex','Location','best');
    xlabel('$\hat{\theta}$','Interpreter','latex');
    ylabel('$J$','Interpreter','latex');
    grid on;
end



figure('Name','Estimate vs Cost RBSs','Color','w');
tiledlayout(1,4,'Padding','compact','TileSpacing','compact');
for i = 1:4
    nexttile
     for j = 1:numel(set_dma)
         h(j) =  scatter(Results_parameters_case{j}.Estimated_parameters.ALL_raw(:,3+i),Results_parameters_case{j}.Estimated_parameters.J_raw,35,RBS_colors(j,:),'filled');
         hold on
     end
     legend(h, labels, 'Interpreter','latex','Location','best');
    xlabel('$\hat{\theta}$','Interpreter','latex');
    ylabel('$J$','Interpreter','latex');
    grid on;
end

 

    